{const tick=()=>{const d=document.documentElement&&document.documentElement.dataset;if(d){const k=!!d.changeKind;if(k){__rec.changeFrames++;if(d.glass==='bend')__rec.bendDuringChange++;if('glassLive' in d)__rec.liveDuringChange=(__rec.liveDuringChange||0)+1;if(document.querySelector('[data-glass-warm]'))__rec.warmHostDuringChange++}}__rec.frames++;requestAnimationFrame(tick)};requestAnimationFrame(tick)}
